"""Freeze evidence for the independently owned Cutlass R02 candidate."""
from pathlib import Path
import json,hashlib,struct
ART=Path(__file__).resolve().parents[1];ROOT=ART.parents[4]
def read(p):return json.loads(Path(p).read_text(encoding='utf-8'))
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def rel(p):return str(Path(p).relative_to(ROOT)).replace('\\','/')
def main():
    a=read(ART/'qa/iteration02/build_manifest.json');rt=read(ART/'qa/iteration02/roundtrip.json');i1=read(ART/'qa/iteration01/build_manifest.json')
    assert a['qa_pass'] and not a['qa_errors'] and not a['qa_warnings'] and rt['pass'] and not rt['errors'] and not rt['warnings']
    assert i1['qa_pass'] and not i1['qa_errors'] and not i1['qa_warnings']
    glb=ROOT/a['export']['path'];assert sha(glb)==a['export']['sha256']==rt['glb_sha256'];assert sha(ROOT/a['source'])==a['source_sha256']
    raw=glb.read_bytes();n=struct.unpack_from('<I',raw,12)[0];g=json.loads(raw[20:20+n]);assert len(g['meshes'])==1 and len(g['materials'])<=10 and len(g['nodes'])==1 and not g.get('skins') and not g.get('animations') and not g.get('images')
    old=read(ROOT/'art/frontier_illustrated_20261101/ships/pass04/manifest.json')['assets'][0]
    assert sha(ROOT/old['source'])==old['source_sha256'] and sha(ROOT/old['export']['path'])==old['export']['sha256']
    refs=[{'path':'docs/reports/assets/grafik-2026-11-01/'+f,'sha256':sha(ROOT/'docs/reports/assets/grafik-2026-11-01'/f),'role':'generated current two-view target, not a game screenshot'} for f in ['08_cutlass_vorne_wimmel.png','09_cutlass_hinten_wimmel.png']]
    a.update({'status':'documented technical intermediate: user also criticized the R02 target deviation; NOT artistically accepted','selected_iteration':2,'normalization':'16 Blender-m total length; explicitly stylized, not canonical Star Citizen dimensions','geometry_provenance':'New original mesh reconstruction after the assigned target pair. No R01/old high-poly/stock ship mesh is imported. Generator utility patterns revised from prior own code; R01 source and export hashes checked unchanged.','reference_images':refs,'roundtrip':rt,'scale_status':'intentionally stylized source length16m, runtime scale0.22','runtime_dimensions_width_length_height_m':[x*.22 for x in a['dimensions_blender_m']],'no_emission':True,'uv':'absent by design for constant-color material fields; UV QA disabled, full geometry QA enabled','collision_navigation_lights_animations':False})
    images=[]
    for iteration in [1,2]:
        qa=ART/'qa'/('iteration%02d'%iteration)
        for p in sorted(qa.glob('*.png')):images.append({'path':rel(p),'sha256':sha(p),'iteration':iteration,'opened':True,'kind':'EEVEE fresh GLB comparison' if p.name.startswith('presentation_') else ('fresh GLB Workbench' if p.name.startswith('roundtrip_') else ('R01 matched Workbench' if p.name.startswith('r01_matched_') else 'editable source Workbench'))})
    scripts=[{'path':rel(p),'sha256':sha(p)} for p in sorted((ART/'generator').glob('*.py'))]
    out={'schema':'sternenbuergerchen.cutlass_pass04_r02.v1','task':'docs/tasks/ART_2026_11_01_pass04.md','status':'Cutlass iteration02 frozen for parent-owned native integration, visual candidate','assets':[a],'selected_iteration':2,'previous_user_verdict':{'revision':'pass04 R01','status':'explicitly rejected artistically by user; historical comparison only'},'iterations':[{'iteration':1,'role':'retained broad-form study, not native selection','source':i1['source'],'source_sha256':i1['source_sha256'],'export':i1['export'],'triangles':i1['triangles'],'qa_pass':i1['qa_pass'],'images':'qa/iteration01/'},{'iteration':2,'role':'selected new candidate; structural roof/wing insets, panelled ramp, joined cowl, sparse fasteners, warm recessed nozzles','source':a['source'],'export':a['export'],'qa_pass':a['qa_pass'],'images':'qa/iteration02/'}],'previous_r01_preserved':{'source':old['source'],'source_sha256':old['source_sha256'],'export':old['export'],'triangles':old['triangles']},'measured_form_comparison':read(ART/'qa/iteration02/form_comparison.json'),'visual_review':{'opened':True,'improvement_over_r01':'Much fuller blunt cockpit, thicker shaped forward shoulders, broader sloped cargo hull, true inset side/roof fields and segmented structural cowls. Iteration02 gives the formerly blank roof and black rear a readable panel structure; large color regions and twelve isolated fasteners stay sparse.','remaining_differences':'Cleaner and more symmetrical than the painted targets, less broken industrial layering, simplified engine joint and canopy window contours. The central spine remains relatively broad; no painted wear or texture-based illustration. Original static landing supports are functional display geometry, not canonical landing gear. Candidate appearance requires native/user review.','comparison_conditions':'R01/R02 Workbench Front/Rear/Game cameras matched in direction, target and orthographic size. Additional fresh-GLB EEVEE pairs match camera, lighting, exposure and resolution. WB and EEVEE are distinct routes, not native Godot capture.','normal_precision':'Position/material triangle data exact; measured bidirectional corner-normal discrepancy0.3033degrees after encoding/reconstruction, explicitly retained rather than claimed exact.'},'opened_images':images,'generator_files':scripts,'qa_history':'Initial raw reports retained as initial_source_raw_failed.json. Generated bevel collapses, eight initially floating fasteners and hidden ramp cap contacts were corrected. Both retained final iterations pass SourceQA without errors/warnings; selected GLB passes fresh raw QA without errors/warnings.','not_claimed':['user art approval','canonical Star Citizen dimensions or original game mesh provenance','native Godot verification by this subtask','flight or weapon mechanisms','general performance/release acceptance']}
    out['status']='R02 iteration02 frozen technical intermediate; user criticized remaining reference deviation; no artistic acceptance'
    out['r02_user_verdict']={'status':'reference deviation still criticized; this revision is a documented technical intermediate','continuation':'User explicitly requested a separate Astra Ultra chat for both ships; parent started chat01a197d8-ebd0-7100-8d12-21ff6bc52c0d. No further modeling round in this subtask.'}
    out['native_integration_status']='Parent reports R02 native import/capture performed; this manifest retains Blender source/GLB evidence only, native capture evidence belongs to the separate report.'
    out['visual_review']['acceptance']='Measured form improvements are a comparison finding only. User subsequently criticized the R02 reference gap; no artistic approval and no finished ship art claimed.'
    (ART/'manifest.json').write_text(json.dumps(out,indent=2),encoding='utf-8');print(json.dumps({'manifest':rel(ART/'manifest.json'),'selected_iteration':2,'sha256':a['export']['sha256'],'triangles':a['triangles'],'opened_images':len(images)}))
if __name__=='__main__':main()
